const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/contract_detail_items/%7Bid%7D',
  qs: {project_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    requisition_contract_detail_item: {
      work_completed_this_period: 1000,
      materials_presently_stored: 500,
      work_completed_retainage_retained_this_period: 100,
      materials_stored_retainage_currently_retained: 50,
      work_completed_retainage_released_this_period: 0,
      work_completed_this_period_quantity: 10
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/contract_detail_items/%7Bid%7D?project_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"requisition_contract_detail_item\":{\"work_completed_this_period\":1000,\"materials_presently_stored\":500,\"work_completed_retainage_retained_this_period\":100,\"materials_stored_retainage_currently_retained\":50,\"work_completed_retainage_released_this_period\":0,\"work_completed_this_period_quantity\":10}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
